import type { Course, Hole, ObstacleDescriptor, SurfaceDescriptor } from '../types';
import type { Vec3 } from '../../contracts/math';

const v = (x: number, y: number, z: number): Vec3 => ({ x, y, z });
const floor = (id: string, z: number, length: number, width = 7, material: SurfaceDescriptor['material'] = 'stone'): SurfaceDescriptor => ({ id, transform: { position: v(0, 0, z) }, shape: 'box', size: v(width, 0.4, length), material, friction: material === 'sand' ? 0.9 : 0.48 });
const wall = (id: string, x: number, z: number, sx: number, sz: number): ObstacleDescriptor => ({ id, type: 'wall', transform: { position: v(x, 0.7, z) }, size: v(sx, 1.4, sz), restitution: 0.18 });
const pillar = (id: string, x: number, z: number, size = 1.1): ObstacleDescriptor => ({ id, type: 'pillar', transform: { position: v(x, 0.8, z) }, size: v(size, 1.6, size), restitution: 0.25 });
const spinner = (id: string, z: number, speed: number): ObstacleDescriptor => ({ id, type: 'spinner', transform: { position: v(0, 0.7, z) }, size: v(5.2, 0.45, 0.55), motion: { kind: 'rotate', axis: v(0, 1, 0), speed } });
const hazard = (id: string, z: number, width: number, length: number): ObstacleDescriptor => ({ id, type: 'void', transform: { position: v(0, -0.2, z) }, size: v(width, 0.5, length), penaltyStrokes: 1 });
const makeHole = (n: number, name: string, par: number, length: number, obstacles: ObstacleDescriptor[], surfaces: SurfaceDescriptor[] = []): Hole => ({ id: `ancient-temple-${n}`, name, par, spawn: v(0, 0.55, 2), cup: { position: v(0, 0.25, length - 2), radius: 0.34, captureDepth: 0.3 }, bounds: { min: v(-8, -4, -2), max: v(8, 8, length + 3) }, surfaces: [floor(`temple-floor-${n}`, length / 2, length), ...surfaces], obstacles: [wall(`left-${n}`, -3.7, length / 2, 0.35, length), wall(`right-${n}`, 3.7, length / 2, 0.35, length), ...obstacles] });

export const ancientTempleCourse: Course = {
  id: 'ancient-temple', name: 'Ancient Temple', themeId: 'ancient-temple', version: 1,
  holes: [
    makeHole(1, 'Processional Way', 2, 18, [pillar('guardian-1', 0, 10, 1.2)]),
    makeHole(2, 'Twin Idols', 3, 22, [pillar('idol-2a', -1.5, 11), pillar('idol-2b', 1.5, 11)]),
    makeHole(3, 'Broken Colonnade', 3, 25, [pillar('col-3a', -1.8, 9), pillar('col-3b', 1.5, 15), pillar('col-3c', -1.2, 20)]),
    makeHole(4, 'Sand of Ages', 3, 27, [pillar('idol-4', 0, 15)], [{ id: 'sand-4', transform: { position: v(0, 0.25, 13) }, shape: 'box', size: v(6.5, 0.12, 5), material: 'sand', friction: 0.95 }]),
    makeHole(5, 'Sun Dial', 4, 29, [spinner('dial-5', 15, 0.75), pillar('dial-post-5', 0, 15, 0.8)]),
    makeHole(6, 'Collapsed Court', 4, 31, [hazard('pit-6', 17, 3.5, 4), pillar('court-6a', -2, 12), pillar('court-6b', 2, 23)]),
    makeHole(7, 'Priests Gate', 4, 34, [{ id: 'gate-7', type: 'gate', transform: { position: v(0, 0.8, 18) }, size: v(3.8, 1.6, 0.5), motion: { kind: 'translate', axis: v(1, 0, 0), speed: 1.1, distance: 2.2 } }, pillar('gate-7a', -2.7, 18), pillar('gate-7b', 2.7, 18)]),
    makeHole(8, 'Serpent Passage', 5, 37, [pillar('serpent-8a', -1.8, 10), pillar('serpent-8b', 1.8, 16), pillar('serpent-8c', -1.8, 22), spinner('serpent-8d', 29, 1.05)]),
